def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_sessions_keeps_last_duplicate_id():
    earlier = {"id": "same", "day": 1, "converted": True}
    later = {"id": "same", "day": 4, "converted": False}
    other = {"id": "other", "day": 2, "converted": True}
    assert dedupe_sessions([earlier, other, later]) == [other, later]


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}] * 3,
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window_uses_last_days():
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 10) == 6


def test_parse_session_log_values_and_skips():
    assert parse_session_log([
        "  # comment",
        "  ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


def test_parse_session_log_errors_include_original_line_number():
    with pytest.raises(ValueError, match="line 2"):
        parse_session_log(["# comment", "bad,line"])
    with pytest.raises(ValueError, match="line 1"):
        parse_session_log(["id,not-a-day,1"])


def test_daily_counts_cover_range_and_ignore_outside():
    events = [
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 1, "converted": None},
        {"day": 3, "converted": True},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [1, 0, 1]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_rounding_recent_and_nonempty_groups():
    groups = {
        "converted": [{"id": "a", "day": 1, "converted": True}],
        "empty": [],
        "not-converted": [
